<#
  갤러리 장소별 분리 + 제목에 구글 지도 링크 + 랜덤 대표 사진

  이 스크립트 하나로 아래 3개 파일을 최신 상태로 덮어씁니다.
  앞서 드린 apply-gallery-groups.ps1 / apply-gallery-maplink.ps1 을
  실행했는지 여부와 관계없이, 이것만 실행하면 됩니다.

    src\lib\assets.js                          폴더별 수집 + 랜덤 대표 사진
    src\config\invitationConfig.js              gallery.groups, mainPhoto: 'random'
    src\components\common\GallerySection.jsx    장소별 블록 + 제목 = 지도 링크

  두는 곳: C:\Users\sb622\OneDrive\문서\GitHub\mobile-invitation\apply-gallery-all.ps1
  실행:
      cd "C:\Users\sb622\OneDrive\문서\GitHub\mobile-invitation"
      powershell -ExecutionPolicy Bypass -File .\apply-gallery-all.ps1

  ⚠️ 사진이 장소별 폴더로 옮겨져 있어야 합니다 (move-gallery-folders.ps1).

  되돌리려면:
      git checkout -- src/lib/assets.js src/config/invitationConfig.js src/components/common/GallerySection.jsx
#>

$ErrorActionPreference = 'Stop'

if (-not (Test-Path .\package.json)) {
  Write-Host '프로젝트 폴더에서 실행하세요 (package.json 이 있는 곳).' -ForegroundColor Red
  Write-Host ('현재 위치: ' + (Get-Location)) -ForegroundColor Yellow
  exit 1
}

function Write-ProjectFile {
  param([string]$Path, [string]$Base64)
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) {
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
  }
  [IO.File]::WriteAllBytes(
    (Join-Path (Get-Location) $Path),
    [Convert]::FromBase64String($Base64)
  )
  Write-Host ('  덮어씀  ' + $Path)
}

